const metrics = $json;
const conflictClearanceRate = metrics.totalIntakes ? Math.round((metrics.conflictCleared / metrics.totalIntakes) * 100) : 0;
const slaHitRate = metrics.conflictCleared ? Math.round((metrics.callbacksUnder4h / metrics.conflictCleared) * 100) : 0;
const engagementRate = metrics.discoveryHeld ? Math.round((metrics.engaged / metrics.discoveryHeld) * 100) : 0;
const digest = `Legal Intake Weekly Digest
Firm: ${metrics.firmName}
Period: ${metrics.period}

Total intakes: ${metrics.totalIntakes}
Conflict-cleared: ${metrics.conflictCleared} (${conflictClearanceRate}%)
Conflicts declined: ${metrics.conflictsDeclined}
Callbacks under 4h SLA: ${metrics.callbacksUnder4h} (${slaHitRate}%)

Discovery scheduled: ${metrics.discoveryScheduled}
Discovery held: ${metrics.discoveryHeld}
Engagements signed: ${metrics.engaged} (${engagementRate}% of held discoveries)

Review opportunities: ${metrics.reviewOpportunities}
Reviews requested: ${metrics.reviewsRequested}
Workflow failures: ${metrics.workflowFailures}

Note: Aggregate metrics only. No prospective-client information appears in this digest.`;
return [{ json: { ...metrics, conflictClearanceRate, slaHitRate, engagementRate, digest } }];
